# Esquemas congelados para la adopción de claves foráneas; no editar tras aplicar la migración.
SQLITE = "PRAGMA foreign_keys = ON;\n\n-- =========================================\n-- 1. USUARIOS\n-- Anfitriones y Administradores\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS usuarios (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    nombre TEXT NOT NULL,\n    correo TEXT NOT NULL UNIQUE,\n    telefono TEXT NOT NULL DEFAULT '',\n    password_hash TEXT NOT NULL,\n    rol TEXT NOT NULL\n        CHECK (rol IN ('ANFITRION', 'ADMINISTRADOR')),\n    activo INTEGER NOT NULL DEFAULT 1\n        CHECK (activo IN (0, 1)),\n    fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\n\n-- =========================================\n-- 2. PLANTILLAS DE SESION\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS plantillas_sesion (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    nombre TEXT NOT NULL UNIQUE,\n    descripcion TEXT,\n    activa INTEGER NOT NULL DEFAULT 1\n        CHECK (activa IN (0, 1)),\n    fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\n\n-- =========================================\n-- 3. CAMPOS DE LAS PLANTILLAS\n-- Definen los datos propios de cada Sesion\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS campos_plantilla (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    plantilla_id INTEGER NOT NULL,\n    nombre TEXT NOT NULL,\n    etiqueta TEXT NOT NULL,\n    tipo TEXT NOT NULL DEFAULT 'texto'\n        CHECK (\n            tipo IN (\n                'texto',\n                'numero',\n                'fecha',\n                'hora',\n                'email'\n            )\n        ),\n    obligatorio INTEGER NOT NULL DEFAULT 0\n        CHECK (obligatorio IN (0, 1)),\n    orden INTEGER NOT NULL DEFAULT 0,\n\n    FOREIGN KEY (plantilla_id)\n        REFERENCES plantillas_sesion(id)\n        ON DELETE RESTRICT,\n\n    UNIQUE (plantilla_id, nombre)\n);\n\n\n-- =========================================\n-- 4. SESIONES\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS sesiones (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n\n    plantilla_id INTEGER NOT NULL,\n    anfitrion_id INTEGER,\n\n    nombre TEXT NOT NULL,\n    fecha_inicio TEXT,\n    fecha_cierre TEXT,\n\n    estado TEXT NOT NULL DEFAULT 'ABIERTA'\n        CHECK (estado IN ('PROGRAMADA', 'ABIERTA', 'CERRADA')),\n\n    token_qr TEXT NOT NULL UNIQUE,\n\n    -- Copia de la definicion de campos de la\n    -- plantilla al crear la Sesion.\n    campos_definicion_json TEXT NOT NULL DEFAULT '{}',\n\n    -- Valores concretos de los campos de esta Sesion.\n    campos_valores_json TEXT NOT NULL DEFAULT '{}',\n\n    fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n\n    FOREIGN KEY (plantilla_id)\n        REFERENCES plantillas_sesion(id)\n        ON DELETE RESTRICT,\n\n    FOREIGN KEY (anfitrion_id)\n        REFERENCES usuarios(id)\n        ON DELETE RESTRICT\n);\n\n\n-- =========================================\n-- 5. ASISTENTES\n-- Datos reutilizables entre Sesiones\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS asistentes (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    rut TEXT UNIQUE,\n    nombre TEXT NOT NULL,\n    telefono TEXT NOT NULL,\n    correo TEXT NOT NULL,\n    fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    fecha_actualizacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\n\n-- =========================================\n-- 6. ASISTENCIAS\n-- Conservan una copia historica de los datos\n-- del Asistente al momento del registro.\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS asistencias (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n\n    sesion_id INTEGER NOT NULL,\n    asistente_id INTEGER NOT NULL,\n\n    nombre_registrado TEXT NOT NULL,\n    cargo_registrado TEXT NOT NULL DEFAULT '',\n    campos_participante_json TEXT NOT NULL DEFAULT '{}',\n    registro_token TEXT UNIQUE,\n    rut_registrado TEXT NOT NULL,\n    telefono_registrado TEXT NOT NULL,\n    correo_registrado TEXT NOT NULL,\n\n    estado TEXT NOT NULL DEFAULT 'PENDIENTE_FIRMA'\n        CHECK (\n            estado IN (\n                'PENDIENTE_FIRMA',\n                'FIRMADO',\n                'ANULADO'\n            )\n        ),\n\n    fecha_registro TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    fecha_firma TEXT,\n\n    FOREIGN KEY (sesion_id)\n        REFERENCES sesiones(id)\n        ON DELETE RESTRICT,\n\n    FOREIGN KEY (asistente_id)\n        REFERENCES asistentes(id)\n        ON DELETE RESTRICT,\n\n    -- Un Asistente solo puede registrar\n    -- una Asistencia por Sesion.\n    UNIQUE (sesion_id, asistente_id)\n);\n\n\n-- =========================================\n-- 7. FIRMAS\n-- La imagen se almacena como un BLOB.\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS firmas (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n\n    asistencia_id INTEGER NOT NULL UNIQUE,\n\n    imagen BLOB NOT NULL,\n    formato TEXT NOT NULL DEFAULT 'image/png',\n    fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n\n    FOREIGN KEY (asistencia_id)\n        REFERENCES asistencias(id)\n        ON DELETE RESTRICT\n);\n\n\n-- =========================================\n-- 8. AUDITORIA\n-- Registro de acciones relevantes.\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS auditoria (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n\n    usuario_id INTEGER,\n    accion TEXT NOT NULL,\n    entidad TEXT NOT NULL,\n    entidad_id INTEGER,\n\n    datos_anteriores_json TEXT,\n    datos_nuevos_json TEXT,\n\n    fecha TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n\n    FOREIGN KEY (usuario_id)\n        REFERENCES usuarios(id)\n        ON DELETE RESTRICT\n);\n\n\n-- =========================================\n-- 9. INDICES\n-- Optimizan consultas habituales.\n-- =========================================\n\nCREATE INDEX IF NOT EXISTS idx_sesiones_fecha\n    ON sesiones(fecha_inicio);\n\nCREATE INDEX IF NOT EXISTS idx_sesiones_tipo\n    ON sesiones(plantilla_id);\n\nCREATE INDEX IF NOT EXISTS idx_sesiones_anfitrion\n    ON sesiones(anfitrion_id);\n\nCREATE INDEX IF NOT EXISTS idx_asistencias_sesion\n    ON asistencias(sesion_id);\n\nCREATE INDEX IF NOT EXISTS idx_asistencias_asistente\n    ON asistencias(asistente_id);\n\nCREATE INDEX IF NOT EXISTS idx_asistencias_estado\n    ON asistencias(estado);\n\nCREATE INDEX IF NOT EXISTS idx_auditoria_fecha\n    ON auditoria(fecha);\nCREATE TABLE IF NOT EXISTS firmas_devolucion (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    asistencia_id INTEGER NOT NULL UNIQUE REFERENCES asistencias(id) ON DELETE RESTRICT,\n    imagen BLOB NOT NULL,\n    formato TEXT NOT NULL DEFAULT 'image/png',\n    fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS firmas_adicionales (\n    id INTEGER PRIMARY KEY AUTOINCREMENT,\n    asistencia_id INTEGER NOT NULL REFERENCES asistencias(id) ON DELETE RESTRICT,\n    tipo TEXT NOT NULL CHECK(tipo IN ('DOCENTE')),\n    imagen BLOB NOT NULL,\n    formato TEXT NOT NULL DEFAULT 'image/png',\n    fecha_creacion TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE(asistencia_id, tipo)\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_usuarios_correo_ci ON usuarios(lower(correo));\n"
POSTGRESQL = "\n-- =========================================\n-- 1. USUARIOS\n-- Anfitriones y Administradores\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS usuarios (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    nombre TEXT NOT NULL,\n    correo TEXT NOT NULL UNIQUE,\n    telefono TEXT NOT NULL DEFAULT '',\n    password_hash TEXT NOT NULL,\n    rol TEXT NOT NULL\n        CHECK (rol IN ('ANFITRION', 'ADMINISTRADOR')),\n    activo INTEGER NOT NULL DEFAULT 1\n        CHECK (activo IN (0, 1)),\n    fecha_creacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text)\n);\n\n\n-- =========================================\n-- 2. PLANTILLAS DE SESION\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS plantillas_sesion (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    nombre TEXT NOT NULL UNIQUE,\n    descripcion TEXT,\n    activa INTEGER NOT NULL DEFAULT 1\n        CHECK (activa IN (0, 1)),\n    fecha_creacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text)\n);\n\n\n-- =========================================\n-- 3. CAMPOS DE LAS PLANTILLAS\n-- Definen los datos propios de cada Sesion\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS campos_plantilla (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    plantilla_id BIGINT NOT NULL,\n    nombre TEXT NOT NULL,\n    etiqueta TEXT NOT NULL,\n    tipo TEXT NOT NULL DEFAULT 'texto'\n        CHECK (\n            tipo IN (\n                'texto',\n                'numero',\n                'fecha',\n                'hora',\n                'email'\n            )\n        ),\n    obligatorio INTEGER NOT NULL DEFAULT 0\n        CHECK (obligatorio IN (0, 1)),\n    orden INTEGER NOT NULL DEFAULT 0,\n\n    FOREIGN KEY (plantilla_id)\n        REFERENCES plantillas_sesion(id)\n        ON DELETE RESTRICT,\n\n    UNIQUE (plantilla_id, nombre)\n);\n\n\n-- =========================================\n-- 4. SESIONES\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS sesiones (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n\n    plantilla_id BIGINT NOT NULL,\n    anfitrion_id BIGINT,\n\n    nombre TEXT NOT NULL,\n    fecha_inicio TEXT,\n    fecha_cierre TEXT,\n\n    estado TEXT NOT NULL DEFAULT 'ABIERTA'\n        CHECK (estado IN ('PROGRAMADA', 'ABIERTA', 'CERRADA')),\n\n    token_qr TEXT NOT NULL UNIQUE,\n\n    -- Copia de la definicion de campos de la\n    -- plantilla al crear la Sesion.\n    campos_definicion_json TEXT NOT NULL DEFAULT '{}',\n\n    -- Valores concretos de los campos de esta Sesion.\n    campos_valores_json TEXT NOT NULL DEFAULT '{}',\n\n    fecha_creacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),\n\n    FOREIGN KEY (plantilla_id)\n        REFERENCES plantillas_sesion(id)\n        ON DELETE RESTRICT,\n\n    FOREIGN KEY (anfitrion_id)\n        REFERENCES usuarios(id)\n        ON DELETE RESTRICT\n);\n\n\n-- =========================================\n-- 5. ASISTENTES\n-- Datos reutilizables entre Sesiones\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS asistentes (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    rut TEXT UNIQUE,\n    nombre TEXT NOT NULL,\n    telefono TEXT NOT NULL,\n    correo TEXT NOT NULL,\n    fecha_creacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),\n    fecha_actualizacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text)\n);\n\n\n-- =========================================\n-- 6. ASISTENCIAS\n-- Conservan una copia historica de los datos\n-- del Asistente al momento del registro.\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS asistencias (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n\n    sesion_id BIGINT NOT NULL,\n    asistente_id BIGINT NOT NULL,\n\n    nombre_registrado TEXT NOT NULL,\n    cargo_registrado TEXT NOT NULL DEFAULT '',\n    campos_participante_json TEXT NOT NULL DEFAULT '{}',\n    registro_token TEXT UNIQUE,\n    rut_registrado TEXT NOT NULL,\n    telefono_registrado TEXT NOT NULL,\n    correo_registrado TEXT NOT NULL,\n\n    estado TEXT NOT NULL DEFAULT 'PENDIENTE_FIRMA'\n        CHECK (\n            estado IN (\n                'PENDIENTE_FIRMA',\n                'FIRMADO',\n                'ANULADO'\n            )\n        ),\n\n    fecha_registro TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),\n    fecha_firma TEXT,\n\n    FOREIGN KEY (sesion_id)\n        REFERENCES sesiones(id)\n        ON DELETE RESTRICT,\n\n    FOREIGN KEY (asistente_id)\n        REFERENCES asistentes(id)\n        ON DELETE RESTRICT,\n\n    -- Un Asistente solo puede registrar\n    -- una Asistencia por Sesion.\n    UNIQUE (sesion_id, asistente_id)\n);\n\n\n-- =========================================\n-- 7. FIRMAS\n-- La imagen se almacena como un BLOB.\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS firmas (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n\n    asistencia_id BIGINT NOT NULL UNIQUE,\n\n    imagen BYTEA NOT NULL,\n    formato TEXT NOT NULL DEFAULT 'image/png',\n    fecha_creacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),\n\n    FOREIGN KEY (asistencia_id)\n        REFERENCES asistencias(id)\n        ON DELETE RESTRICT\n);\n\n\n-- =========================================\n-- 8. AUDITORIA\n-- Registro de acciones relevantes.\n-- =========================================\n\nCREATE TABLE IF NOT EXISTS auditoria (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n\n    usuario_id BIGINT,\n    accion TEXT NOT NULL,\n    entidad TEXT NOT NULL,\n    entidad_id BIGINT,\n\n    datos_anteriores_json TEXT,\n    datos_nuevos_json TEXT,\n\n    fecha TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),\n\n    FOREIGN KEY (usuario_id)\n        REFERENCES usuarios(id)\n        ON DELETE RESTRICT\n);\n\n\n-- =========================================\n-- 9. INDICES\n-- Optimizan consultas habituales.\n-- =========================================\n\nCREATE INDEX IF NOT EXISTS idx_sesiones_fecha\n    ON sesiones(fecha_inicio);\n\nCREATE INDEX IF NOT EXISTS idx_sesiones_tipo\n    ON sesiones(plantilla_id);\n\nCREATE INDEX IF NOT EXISTS idx_sesiones_anfitrion\n    ON sesiones(anfitrion_id);\n\nCREATE INDEX IF NOT EXISTS idx_asistencias_sesion\n    ON asistencias(sesion_id);\n\nCREATE INDEX IF NOT EXISTS idx_asistencias_asistente\n    ON asistencias(asistente_id);\n\nCREATE INDEX IF NOT EXISTS idx_asistencias_estado\n    ON asistencias(estado);\n\nCREATE INDEX IF NOT EXISTS idx_auditoria_fecha\n    ON auditoria(fecha);\nCREATE TABLE IF NOT EXISTS firmas_devolucion (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    asistencia_id BIGINT NOT NULL UNIQUE REFERENCES asistencias(id) ON DELETE RESTRICT,\n    imagen BYTEA NOT NULL,\n    formato TEXT NOT NULL DEFAULT 'image/png',\n    fecha_creacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text)\n);\n\nCREATE TABLE IF NOT EXISTS firmas_adicionales (\n    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,\n    asistencia_id BIGINT NOT NULL REFERENCES asistencias(id) ON DELETE RESTRICT,\n    tipo TEXT NOT NULL CHECK(tipo IN ('DOCENTE')),\n    imagen BYTEA NOT NULL,\n    formato TEXT NOT NULL DEFAULT 'image/png',\n    fecha_creacion TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text),\n    UNIQUE(asistencia_id, tipo)\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS idx_usuarios_correo_ci ON usuarios(lower(correo));\n"
